// @category GFZ
import ghidra.app.script.GhidraScript;import ghidra.program.model.listing.*;import ghidra.program.model.symbol.*;import java.util.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class ScanUnresolvedQualifiedSymbols extends GhidraScript{
 static boolean pref(Function f,String p){for(FunctionTag t:f.getTags())if(t.getName().startsWith(p))return true;return false;} static boolean tag(Function f,String n){for(FunctionTag t:f.getTags())if(t.getName().equals(n))return true;return false;} static boolean free(Function f){return !pref(f,"GFZ.V120.PrimaryOwner.")&&!tag(f,"GFZ.V120.FinalNoPrimaryOwner")&&!pref(f,"GFZ.V121.CodeDomain.");}
 public void run()throws Exception{String[]a=getScriptArgs();if(a.length!=1)throw new IllegalArgumentException("out");Listing li=currentProgram.getListing();SymbolTable st=currentProgram.getSymbolTable();ArrayList<String>rows=new ArrayList<>();int phy=0,std=0;FunctionIterator it=currentProgram.getFunctionManager().getFunctions(true);while(it.hasNext()){Function f=it.next();if(f.isExternal()||!free(f))continue;TreeSet<String>sy=new TreeSet<>();InstructionIterator ii=li.getInstructions(f.getBody(),true);while(ii.hasNext()){Instruction x=ii.next();for(Reference r:x.getReferencesFrom()){Symbol s=st.getPrimarySymbol(r.getToAddress());if(s!=null){String n=s.getName(true);if(n.contains("Phyre::")||n.contains("std::")||n.contains("eastl::"))sy.add(n);}}}if(!sy.isEmpty()){boolean p=sy.stream().anyMatch(x->x.contains("Phyre::"));if(p)phy++;else std++;rows.add(String.format("%08X\t%d\t%s",f.getEntryPoint().getOffset(),f.getBody().getNumAddresses(),String.join(" | ",sy)));}}
 try(PrintWriter w=new PrintWriter(new OutputStreamWriter(new FileOutputStream(a[0]),StandardCharsets.UTF_8))){w.println("entry\tbody_bytes\tqualified_symbols");for(String s:rows)w.println(s);}println("UNRESOLVED_QUALIFIED_SYMBOLS total="+rows.size()+" phyre="+phy+" stdEastlOnly="+std);}
}
